-- LemmaYard problem catalog for Supabase, part 4 of 6 (SQL Editor -> New query -> paste -> Run).
-- Generated by `pnpm problems:export-sql` from problems/*; do not edit by hand.
-- The same catalog in one file is docs/supabase/problems.sql; the parts exist for SQL
-- editors that refuse a large paste. Run all 6 parts, in any order, after
-- docs/supabase/schema.sql (or `pnpm db:migrate`). Each part is its own transaction
-- over 8 problems, 10 tags and 937 test cases (catalog: 50 problems,
-- 6625 test cases). It writes the same rows as `pnpm problems:import`: upsert by
-- slug (published), tags, and a full replacement of each problem's tags and test cases.
-- Safe to run again; it never unpublishes problems that are not listed here.
-- NOTE: this file contains the HIDDEN test cases too (is_sample = false). They are
-- public anyway, because problems/*/tests.json is committed to this repository.

BEGIN;

-- Refuse to run if another problem in the database already uses one of these numbers.
DO $$
DECLARE taken text;
BEGIN
  SELECT string_agg("slug" || ' (' || "number" || ')', ', ') INTO taken
  FROM "problems"
  WHERE "number" IN (11, 12, 47, 30, 9, 42, 16, 28)
    AND "slug" NOT IN ($ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$ore-pile-merging$ly$, $ly$pair-sum-under-cap$ly$, $ly$palindrome-number$ly$, $ly$prefix-favorites$ly$, $ly$product-of-array-except-self$ly$, $ly$range-count-queries$ly$);
  IF taken IS NOT NULL THEN
    RAISE EXCEPTION 'problem numbers already used by other problems in the database: %', taken;
  END IF;
END $$;

-- Park the numbers of existing rows so renumbering between them cannot collide;
-- every parked row gets its real number back from the upserts below.
UPDATE "problems" SET "number" = "number" + 1000000000
WHERE "slug" IN ($ly$maximum-subarray$ly$, $ly$merge-intervals$ly$, $ly$ore-pile-merging$ly$, $ly$pair-sum-under-cap$ly$, $ly$palindrome-number$ly$, $ly$prefix-favorites$ly$, $ly$product-of-array-except-self$ly$, $ly$range-count-queries$ly$);

INSERT INTO "tags" ("slug", "name") VALUES
  ($ly$array$ly$, $ly$Array$ly$),
  ($ly$dynamic-programming$ly$, $ly$Dynamic Programming$ly$),
  ($ly$sorting$ly$, $ly$Sorting$ly$),
  ($ly$prefix-sum$ly$, $ly$Prefix Sum$ly$),
  ($ly$two-pointers$ly$, $ly$Two Pointers$ly$),
  ($ly$math$ly$, $ly$Math$ly$),
  ($ly$trie$ly$, $ly$Trie$ly$),
  ($ly$string$ly$, $ly$String$ly$),
  ($ly$hash-table$ly$, $ly$Hash Table$ly$),
  ($ly$binary-search$ly$, $ly$Binary Search$ly$)
ON CONFLICT ("slug") DO NOTHING;

-- ---- maximum-subarray ----
INSERT INTO "problems" ("number", "slug", "title", "difficulty", "description_md", "signature", "compare", "time_limit_ms", "memory_limit_mb", "published", "author_rating", "languages", "wide_ints")
VALUES (11, $ly$maximum-subarray$ly$, $ly$Maximum Subarray$ly$, $ly$easy$ly$, $ly$You are given a non-empty integer array `nums`. Pick a contiguous block of it that contains at least one element and add up its values. Return the largest total any such block can have.

When every value is negative, the best block is the single largest element, since the block may not be empty.

## Constraints

- `1 <= nums.length <= 10^4`
- `-10^4 <= nums[i] <= 10^4`

## Notes

- Checking every possible block works for small inputs; a single pass over the array is enough to handle the largest ones comfortably.
$ly$, $ly${"name":"maxSubArray","params":[{"name":"nums","type":"int[]"}],"returns":"int"}$ly$::jsonb, $ly${"mode":"exact"}$ly$::jsonb, 2000, 256, TRUE, 1420, $ly${"python","javascript","java"}$ly$, $ly${}$ly$)
ON CONFLICT ("slug") DO UPDATE SET
  "number" = EXCLUDED."number",
  "slug" = EXCLUDED."slug",
  "title" = EXCLUDED."title",
  "difficulty" = EXCLUDED."difficulty",
  "description_md" = EXCLUDED."description_md",
  "signature" = EXCLUDED."signature",
  "compare" = EXCLUDED."compare",
  "time_limit_ms" = EXCLUDED."time_limit_ms",
  "memory_limit_mb" = EXCLUDED."memory_limit_mb",
  "published" = EXCLUDED."published",
  "author_rating" = EXCLUDED."author_rating",
  "languages" = EXCLUDED."languages",
  "wide_ints" = EXCLUDED."wide_ints",
  "updated_at" = now();

DELETE FROM "problem_tags" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$maximum-subarray$ly$);
INSERT INTO "problem_tags" ("problem_id", "tag_id")
SELECT (SELECT "id" FROM "problems" WHERE "slug" = $ly$maximum-subarray$ly$), "id" FROM "tags" WHERE "slug" IN ($ly$array$ly$, $ly$dynamic-programming$ly$);

DELETE FROM "test_cases" WHERE "problem_id" = (SELECT "id" FROM "problems" WHERE "slug" = $ly$maximum-subarray$ly$);
